    @FXML
    private void initialize() {
        resultsTable = new ResultsTable(this::regrade);
        detailPane = new StudentDetailPane(
                username -> reports.downloadStudentReport(username, consoleStatus.getScene().getWindow()));
        similarityList = new SimilarityList(username -> resultsTable.select(username));
        statsHolder.getChildren().add(statTiles.view());
        HBox.setHgrow(statTiles.view(), Priority.ALWAYS);
        resultsHolder.getChildren().add(resultsTable.view());
        detailHolder.getChildren().add(detailPane.view());
        similarityHolder.getChildren().add(similarityList.view());
        resultsTable.table().getSelectionModel().selectedItemProperty()
                .addListener((property, before, after) -> {
                    showDetail();
                    updateButtons();
                });
        statusPill = new StatusPill(statusBadge, statusText);
        workflowButtons = new WorkflowButtons(testerImportButton, submissionImportButton, runGradingButton,
                scoreSheetImportButton, writeScoresButton, saveReportsButton);
        testerPanel = new ImportPanel(testerImportButton, testerFolderField, testerBrowser, testerSummary,
                testerSummaryText, testerFilesToggle, testerError);
        submissionPanel = new ImportPanel(submissionImportButton, submissionFolderField,
                submissionBrowser, submissionSummary, submissionSummaryText, submissionFilesToggle, submissionError);
        updateSimilarityTab();
        startSession(Path.of(System.getProperty("java.io.tmpdir")));
        updateButtons();
    }

    private void startSession(Path temporaryRoot) {
        Thread sweep = new Thread(() -> WorkFolders.removeAbandoned(temporaryRoot, Instant.now()),
                "abandoned-workspace-cleanup");
        sweep.setDaemon(true);
        sweep.start();
        try {
            workFolder = WorkFolders.create(temporaryRoot);
            session = new GradingSession(settings, progress, workFolder);
        } catch (IOException exception) {
            findingsConsole.setText("The temporary work folder could not be created: "
                    + Messages.describe(exception) + "\nFree some disk space, then restart the application.");
            testerImportButton.setDisable(true);
            submissionImportButton.setDisable(true);
        }
    }

    @FXML
    private void showHelp() {
        HelpDialog.show(helpButton.getScene().getWindow());
    }

    @FXML
    private void importTesterFiles() {
        FileDialogs.folder("Select Tester-Files folder", testerImportButton.getScene().getWindow())
                .ifPresent(this::importTesterFiles);
    }

    void importTesterFiles(Path source) {
        if (isBusy()) {
            return;
        }
        statusPill.save();
        statusPill.show("Validating tester files");
        consoleStatus.setText("Tester validation in progress");
        tasks.run(() -> session.importTesters(source), "tester-file-validator", this::showTesterResult,
                failure -> {
                    testerImported = true;
                    console.setTesters(ImportResults.testerFailure(failure, session.testersReady()));
                    testerPanel.reject(ImportResults.testerReadFailure(failure, session.testersReady()));
                    showImportFailure("Tester import not completed");
                    if (session.testersReady()) {
                        statusPill.restore();
                        consoleStatus.setText("Folder not accepted; earlier tester files kept");
                    }
                });
    }

    @FXML
    private void importSubmissions() {
        Window window = submissionImportButton.getScene().getWindow();
        if (session != null && session.hasResults()) {
            long graded = progress.snapshot().students().stream()
                    .filter(student -> student.status() != GradingStatus.SKIPPED).count();
            if (!Confirmations.ask(Confirmations.replaceResults(graded), window)) {
                return;
            }
        }
        FileDialogs.folder("Select student submissions folder", window).ifPresent(this::importSubmissions);
    }

    void importSubmissions(Path source) {
        if (isBusy()) {
            return;
        }
        identityPromptOffered = false;
        statusPill.save();
        statusPill.show("Validating submissions");
        consoleStatus.setText("Validation in progress");
        tasks.run(() -> session.importSubmissions(source, (done, total, name) ->
                Platform.runLater(() -> showImportProgress(done, total, name))), "submission-validator",
                results -> {
                    submissionPanel.accept(source.toAbsolutePath().toString());
                    showSubmissions(results);
                }, failure -> {
                    Nodes.show(progressBox, false);
                    boolean kept = !submissions.isEmpty();
                    submissionPanel.reject(ImportResults.submissionRejection(failure, kept));
                    submissionsImported = true;
                    console.setSubmissions(ImportResults.submissionFailure(failure, kept));
                    showImportFailure("Import not completed");
                    if (kept) {
                        // The earlier submissions are still used, so the run's status still holds.
                        statusPill.restore();
                        consoleStatus.setText("Folder not accepted; earlier submissions kept");
                    }
                });
    }

    private void showImportProgress(int done, int total, String name) {
        if (!tasks.running()) {
            return;
        }
        Nodes.show(progressBox, true);
        gradingProgress.setProgress((double) done / total);
        progressText.setText("Preparing " + done + " of " + total + " · " + name);
    }

    private void showImportFailure(String status) {
        consoleTabs.getSelectionModel().select(activityTab);
        refreshConsole();
        statusPill.show("Validation failed");
        consoleStatus.setText(status);
    }

    @FXML
    private void runGrading() {
        long ready = submissions.stream().filter(SubmissionValidationResult::isReadyForGrading).count();
        startRun(session::startGrading, "Grading " + ready + " students");
    }

    @FXML
    private void regradeSelected() {
        resultsTable.selected().map(StudentProgress::username).ifPresent(this::regrade);
    }

    private void regrade(String username) {
        startRun(() -> session.regrade(username), "Regrading " + username);
    }

    @FXML
    private void cancelGrading() {
        try {
            session.cancelGrading();
            consoleStatus.setText("Cancelling: stopping the running programs");
        } catch (SessionRefusal refusal) {
            consoleStatus.setText(refusal.getMessage());
        }
    }

    /** Whether a grading run is still going on. */
    boolean isGrading() {
        return runInProgress;
    }

    private void startRun(Runnable start, String description) {
        if (isBusy() || session == null) {
            return;
        }
        try {
            start.run();
        } catch (SessionRefusal refusal) {
            consoleStatus.setText(refusal.getMessage());
            return;
        }
        runInProgress = true;
        console.setGrading("");
        statusPill.show("Grading in progress", StatusPill.Tone.WORKING);
        consoleTabs.getSelectionModel().select(studentsTab);
        consoleStatus.setText(description);
        gradingProgress.setProgress(ProgressBar.INDETERMINATE_PROGRESS);
        progressText.setText("Starting");
        Nodes.show(progressBox, true);
        Nodes.show(cancelButton, true);
        updateButtons();
        monitor.start();
    }

    private void showRunProgress(ProgressSnapshot snapshot) {
        showSnapshot(snapshot);
        gradingProgress.setProgress(snapshot.total() == 0
                ? ProgressBar.INDETERMINATE_PROGRESS : (double) snapshot.done() / snapshot.total());
        progressText.setText(RunMonitor.progressLine(snapshot));
        findingsConsole.setText(String.join("\n", snapshot.activity()));
        findingsConsole.positionCaret(findingsConsole.getLength());
    }

    private void finishRun(ProgressSnapshot snapshot) {
        showSnapshot(snapshot);
        runInProgress = false;
        Nodes.show(progressBox, false);
        Nodes.show(cancelButton, false);
        statusPill.showRunEnd(session.lastOutcome(), resultsTable.toCheckCount());
        consoleStatus.setText(GradingSummaryText.runEnd(session.lastOutcome(), snapshot));
        // Open the first student to check, or the first student when nobody needs checking.
        Optional<String> toCheckFirst = resultsTable.firstToCheck();
        if (toCheckFirst.isPresent()) {
            resultsTable.select(toCheckFirst.get());
        } else if (resultsTable.selected().isEmpty() && !snapshot.students().isEmpty()) {
            resultsTable.select(snapshot.students().getFirst().username());
        }
        consoleTabs.getSelectionModel().select(studentsTab);
        console.setGrading(GradingSummaryText.format(snapshot, session.reportsFolder())
                + "\nProcess log\n" + String.join("\n", snapshot.activity()) + "\n\n");
        console.setScoreSheet(scoreSheet.status(session.hasResults()));
        refreshConsole();
        updateButtons();
    }

    /** Shows the session's table, similar answers and the selected student's details. */
    private void showSnapshot(ProgressSnapshot snapshot) {
        resultsTable.update(snapshot);
        statTiles.update(snapshot);
        similarityList.update(snapshot.similarPairs());
        updateSimilarityTab();
        showDetail();
    }

    private void showDetail() {
        detailPane.show(resultsTable.selected(), session != null && session.reportsFolder().isPresent());
    }

    private void updateSimilarityTab() {
        long flagged = similarityList.flaggedCount();
        similarityTab.setText(flagged == 0 ? "Similar answers" : "Similar answers (" + flagged + ")");
    }

    /** Saves a copy of the student's report from the latest run to the chosen file. */
